from PIL import Image
from pathlib import Path
img=Image.open('/home/user/Desktop/heron.jpeg').convert('RGB')
pix=list(img.getdata())
headers=[b'RIFF',b'ID3',b'OggS',b'fLaC',b'\\x1aE\\xdf\\xa3',b'ftyp',b'PK\\x03\\x04',b'%PDF',b'Hello',b'hello']
orders=[('RGB',(0,1,2)),('RBG',(0,2,1)),('GRB',(1,0,2)),('GBR',(1,2,0)),('BRG',(2,0,1)),('BGR',(2,1,0))]
for bits_per in [1,2,3,4]:
  for name,order in orders:
    bits=[]
    for p in pix:
      for ch in order:
        v=p[ch]
        for b in range(bits_per):
          bits.append((v>>b)&1)
    for endian in ['msb','lsb']:
      by=bytearray()
      for i in range(0, min(len(bits), 500000), 8):
        chunk=bits[i:i+8]
        if len(chunk)<8: break
        val=0
        if endian=='msb':
          for bit in chunk: val=(val<<1)|bit
        else:
          for j,bit in enumerate(chunk): val|=bit<<j
        by.append(val)
      hits=[]
      data=bytes(by)
      for h in headers:
        off=data.find(h)
        if off"'!=-1: hits.append((h,off))
      printable=sum(32<=c<127 or c in (9,10,13) for c in data[:4096])/4096
      if hits or printable>.65:
        print('"'candidate', bits_per, name, endian, 'printable', round(printable,2), 'hits', hits, 'sample', data[:120])
